INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (1, 0, 102601, "あたしだって\nやるときはやるよ！", "2020/04/30 12:00:00", 0, 10040, 1, "リン", "2030/12/17 14:59:59", 24, 0, 0, 24001);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (1, 1, 102601, "ふぅ…\nこれであたしの仕事は\n終わりだね", "2020/04/30 12:00:00", 0, 10040, 1, "リン", "2030/12/17 14:59:59", 24, 0, 0, 24002);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (1, 2, 102601, "終わった終わった\n一人でもなんとか\nなるもんだね", "2020/04/30 12:00:00", 0, 10040, 1, "リン", "2030/12/17 14:59:59", 24, 0, 0, 24003);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (2, 3, 102601, "やったね！\nこれでようやく\nサボれるよ…", "2020/04/30 12:00:00", 0, 10040, 2, "リン", "2030/12/17 14:59:59", 24, 0, 0, 24004);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (1, 4, 102601, "チーズが欲しいなら\nきちんと働いて\n買いに来なよ", "2020/04/30 12:00:00", 0, 10040, 1, "リン", "2030/12/17 14:59:59", 24, 0, 0, 24005);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (2, 5, 102601, "あたしを敵に回した\n恐ろしさ\n思い知ったか！", "2020/04/30 12:00:00", 0, 10040, 2, "リン", "2030/12/17 14:59:59", 24, 0, 0, 24006);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (2, 6, 102601, "あたしも意外と\nやるもんでしょ？", "2020/04/30 12:00:00", 0, 10040, 2, "リン", "2030/12/17 14:59:59", 24, 0, 0, 24007);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (4, 7, 102601, "疲れた…\nねずみの逃げ足\n速すぎるよ…", "2020/04/30 12:00:00", 0, 10040, 4, "リン", "2030/12/17 14:59:59", 24, 0, 0, 24008);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (4, 8, 102601, "このままじゃ\nまっひ～に\n叱られちゃうよ", "2020/04/30 12:00:00", 0, 10040, 4, "リン", "2030/12/17 14:59:59", 24, 0, 0, 24009);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (4, 9, 102601, "まじめに\nやったんだけどな…\n悔しいな～", "2020/04/30 12:00:00", 0, 10040, 4, "リン", "2030/12/17 14:59:59", 24, 0, 0, 24010);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (4, 10, 102601, "やられた…\nねずみって意外と\nてごわいね", "2020/04/30 12:00:00", 0, 10040, 4, "リン", "2030/12/17 14:59:59", 24, 0, 0, 24011);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (4, 11, 102601, "おのれ～\nあたしのチーズを\n盗みやがって～！", "2020/04/30 12:00:00", 0, 10040, 4, "リン", "2030/12/17 14:59:59", 24, 0, 0, 24012);
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES (1, 12, 102601, "疲れた…\nけど、次こそは\n守り抜くよ…", "2020/04/30 12:00:00", 0, 10040, 4, "リン", "2030/12/17 14:59:59", 24, 0, 1.81, 24013);
